154	    /**
155	     * The owner's salutation for display: the {@link #title} followed by a single space
156	     * and the last name (e.g. {@code "DR Who"}), or just the last name when no title is
157	     * present. Derived from the owner's own fields.
158	     */
159	    @Transient
160	    public String getSalutation() {
161	        if (this.title == null || this.title.isBlank()) {
162	            return this.getLastName();
163	        }
164	        return this.title + " " + this.getLastName();
165	    }
