183	    /**
184	     * The owner's age band derived from {@link #birthDate}, computed against the
185	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} when
186	     * 18 to 64 inclusive, {@code "SENIOR"} when 65 or over. Null when either the birth
187	     * date or the registration date is absent.
188	     */
189	    @Transient
190	    public String getAgeBand() {
191	        if (this.birthDate == null || this.registrationDate == null) {
192	            return null;
193	        }
194	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
195	        if (age < 18) {
196	            return "MINOR";
197	        }
198	        if (age < 65) {
199	            return "ADULT";
200	        }
201	        return "SENIOR";
202	    }
