268	    /**
269	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
270	     */
271	    @Transient
272	    public String getDisplayName() {
273	        return this.getLastName() + ", " + this.getFirstName();
274	    }
275	
276	    /**
277	     * The owner's initials: the upper-cased first letters of firstName and
278	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
279	     */
280	    @Transient
281	    public String getInitials() {
282	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
283	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
284	    }
285	
286	    /**
287	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
288	     * YY is the last two digits of the registration date's year
289	     * (e.g. {@code "NSW-A1B2C3D4-M26"}). Derived from the owner's own fields; null when
290	     * either the customer code or registration date is absent.
291	     */
292	    @Transient
293	    public String getMembershipNumber() {
294	        if (this.customerCode == null || this.registrationDate == null) {
295	            return null;
296	        }
297	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
298	    }
299	
300	    /**
301	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
302	     * contained in the {@code customerCode}, scanning right to left and doubling the
303	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
304	     * own fields; null when the customer code is absent.
305	     */
306	    @Transient
307	    public Integer getCheckDigit() {
308	        if (this.customerCode == null) {
309	            return null;
310	        }
311	        int sum = 0;
312	        boolean dbl = true;
313	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
314	            char c = this.customerCode.charAt(i);
315	            if (c < '0' || c > '9') {
316	                continue;
317	            }
318	            int d = c - '0';
319	            if (dbl) {
320	                d *= 2;
321	                if (d > 9) {
322	                    d -= 9;
323	                }
324	            }
325	            sum += d;
326	            dbl = !dbl;
327	        }
328	        return (10 - (sum % 10)) % 10;
329	    }
330	
331	    /**
332	     * The owner's membership points: a running score built from the owner's own fields.
333	     * Starts at 0 and gains 2 when an email address is present, a further 1 when the owner
334	     * has no namesakes ({@code namesakeCount} is 0), a further 2 when it belongs to a
335	     * household of 3 or more members ({@code householdSize} is 3 or more), and a further 3
336	     * for tenure of more than 365 days (the days from {@link #registrationDate} to the
337	     * current date). A newly created owner has zero tenure, so the pre-tenure factors alone
338	     * top out at 5 points. Derived from the owner's own fields.
339	     */
340	    @Transient
341	    public Integer getMembershipPoints() {
342	        int points = 0;
343	        boolean hasEmail = this.email != null && !this.email.isBlank();
344	        if (hasEmail) {
345	            points += 2;
346	        }
347	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
348	        if (unique) {
349	            points += 1;
350	        }
351	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
352	        if (largeHousehold) {
353	            points += 2;
354	        }
355	        boolean tenured = this.registrationDate != null
356	            && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
357	        if (tenured) {
358	            points += 3;
359	        }
360	        return points;
361	    }
362	
363	    /**
364	     * The owner's membership level: a number from 1 to 4 derived by banding
365	     * {@link #getMembershipPoints()} — 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6
366	     * or more. Derived from the owner's own fields.
367	     */
368	    @Transient
369	    public Integer getMembershipLevel() {
370	        int points = getMembershipPoints();
371	        if (points <= 1) {
372	            return 1;
373	        }
374	        if (points <= 3) {
375	            return 2;
376	        }
377	        if (points <= 5) {
378	            return 3;
379	        }
380	        return 4;
381	    }
