383	    /**
384	     * Fixed city-to-region lookup table. Any city not listed derives locality
385	     * {@code "UNKNOWN"}.
386	     */
387	    private static final Map<String, String> CITY_REGION = Map.of(
388	        "Sydney", "NSW",
389	        "Melbourne", "VIC",
390	        "Brisbane", "QLD");
391	
392	    /**
393	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
394	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
395	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
396	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
397	     * postcode validation).
398	     */
399	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
400	        "NSW", new int[] {2000, 2099},
401	        "VIC", new int[] {3000, 3099},
402	        "QLD", new int[] {4000, 4099});
403	
404	    /**
405	     * Fixed region-to-timezone lookup table, mapping each region to its IANA timezone
406	     * name: NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane.
407	     * Any region not listed (including {@code "UNKNOWN"}) has no timezone.
408	     */
409	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
410	        "NSW", "Australia/Sydney",
411	        "VIC", "Australia/Melbourne",
412	        "QLD", "Australia/Brisbane");
413	
414	    /**
415	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
416	     * Read off the {@code customerCode} prefix (the part before the first {@code '-'}) when
417	     * a customer code is present, otherwise derived straight from the postcode via
418	     * {@link #identityRegion(String)}. Either way this yields the region the customer code
419	     * was built from — NSW/VIC/QLD, or {@code "UNKNOWN"} when the postcode is absent or in
420	     * no known range. Derived from the owner's own fields.
421	     */
422	    @Transient
423	    public String getLocality() {
424	        if (this.customerCode != null) {
425	            int dash = this.customerCode.indexOf('-');
426	            if (dash > 0) {
427	                return this.customerCode.substring(0, dash);
428	            }
429	        }
430	        return identityRegion(this.postcode);
431	    }
432	
433	    /**
434	     * The REGION component of an owner's region-and-hash identity: the region derived from
435	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
436	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
437	     * of truth for the identity's region, so the {@code customerCode} prefix and the
438	     * {@link #getLocality() locality} cannot drift apart.
439	     */
440	    public static String identityRegion(String postcode) {
441	        String region = regionForPostcode(postcode);
442	        return region != null ? region : "UNKNOWN";
443	    }
444	
445	    /**
446	     * The canonical region for a city per the fixed city-to-region table
447	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
448	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
449	     * for the city-to-region mapping, used as the city's region in postcode validation.
450	     */
451	    public static String regionForCity(String city) {
452	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
453	    }
454	
455	    /**
456	     * The canonical region for a 4-digit postcode per the fixed range table
457	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
458	     * is absent, not a well-formed integer, or in no known range. Reads the shared
459	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
460	     * for the identity's region and by postcode validation to range-check a submitted
461	     * postcode against its city's region.
462	     */
463	    public static String regionForPostcode(String postcode) {
464	        if (postcode == null) {
465	            return null;
466	        }
467	        int value;
468	        try {
469	            value = Integer.parseInt(postcode.trim());
470	        } catch (NumberFormatException ex) {
471	            return null;
472	        }
473	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
474	            int[] range = entry.getValue();
475	            if (value >= range[0] && value <= range[1]) {
476	                return entry.getKey();
477	            }
478	        }
479	        return null;
480	    }
481	
482	    /**
483	     * Whether the region is subject to postcode range validation, i.e. has a known
484	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
485	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
486	     */
487	    public static boolean hasPostcodeRange(String region) {
488	        return REGION_POSTCODE_RANGES.containsKey(region);
489	    }
490	
491	    /**
492	     * The owner's IANA timezone, derived from the owner's {@link #getLocality() locality}
493	     * (its region) via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
494	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Null when the
495	     * region is not one of these (e.g. {@code "UNKNOWN"}). Derived from the owner's own
496	     * fields.
497	     */
498	    @Transient
499	    public String getTimezone() {
500	        return REGION_TIMEZONE.get(getLocality());
501	    }
502	
503	    /**
504	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
505	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
506	     */
507	    @Transient
508	    public String getContactPreference() {
509	        boolean hasEmail = this.email != null && !this.email.isBlank();
510	        return hasEmail ? "EMAIL" : "PHONE";
511	    }
512	
513	    /**
514	     * The owner's identity key: a display-only composite value formed as
515	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + (householdId or empty)}.
516	     * The telephone and email are already stored in their normalized forms (E.164 and
517	     * lower-cased), and the household id is derived from the last name and postcode (empty
518	     * for an owner with no postcode). It drives no logic — duplicate detection is keyed on
519	     * the household (same last name and postcode); this value is exposed on the API purely
520	     * for reference. A null or blank part contributes an empty segment. Derived from the
521	     * owner's own fields.
522	     */
523	    @Transient
524	    public String getIdentityKey() {
525	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
526	    }
527	
528	    private static String keyPart(String value) {
529	        return (value == null || value.isBlank()) ? "" : value;
530	    }
531	
532	    /**
533	     * The stored E.164 {@link #telephone} formatted for humans: the country code,
534	     * a space, then the national digits grouped in threes (e.g.
535	     * {@code "+61 412 345 678"}). The {@code '+'} and country code are taken from the
536	     * E.164 value (a {@code '+1'} NANP country code is a single digit, any other is
537	     * treated as two digits, matching the recognized {@code '+61'}/{@code '+1'} forms),
538	     * and the national digits follow in space-separated groups of three. Returns the raw
539	     * value unchanged when it is absent or not a {@code '+'}-prefixed run of digits.
540	     * Derived from the owner's own fields; the raw {@link #telephone} stays E.164.
541	     */
542	    @Transient
543	    public String getTelephoneDisplay() {
544	        if (this.telephone == null || !this.telephone.startsWith("+")) {
545	            return this.telephone;
546	        }
547	        String digits = this.telephone.substring(1);
548	        if (!digits.matches("\\d+")) {
549	            return this.telephone;
550	        }
551	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
552	        if (digits.length() <= countryCodeLength) {
553	            return this.telephone;
554	        }
555	        String countryCode = digits.substring(0, countryCodeLength);
556	        String national = digits.substring(countryCodeLength);
557	        StringBuilder grouped = new StringBuilder();
558	        for (int i = 0; i < national.length(); i += 3) {
559	            if (grouped.length() > 0) {
560	                grouped.append(' ');
561	            }
562	            grouped.append(national, i, Math.min(i + 3, national.length()));
563	        }
564	        return "+" + countryCode + " " + grouped;
565	    }
566	
567	    protected Set<Pet> getPetsInternal() {
568	        if (this.pets == null) {
569	            this.pets = new HashSet<>();
570	        }
571	        return this.pets;
572	    }
573	
574	    protected void setPetsInternal(Set<Pet> pets) {
575	        this.pets = pets;
576	    }
577	
578	    public List<Pet> getPets() {
579	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
580	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
581	        return Collections.unmodifiableList(sortedPets);
582	    }
583	
584	    public void setPets(List<Pet> pets) {
585	        this.pets = new HashSet<>(pets);
586	    }
587	
588	    public void addPet(Pet pet) {
589	        getPetsInternal().add(pet);
590	        pet.setOwner(this);
591	    }
592	
593	    /**
594	     * Return the Pet with the given name, or null if none found for this Owner.
595	     *
596	     * @param name to test
597	     * @return true if pet name is already in use
598	     */
599	    public Pet getPet(String name) {
600	        return getPet(name, false);
601	    }
602	
603	    /**
604	     * Return the Pet with the given name, or null if none found for this Owner.
605	     *
606	     * @param name to test
607	     * @return true if pet name is already in use
608	     */
609	    public Pet getPet(String name, boolean ignoreNew) {
610	        name = name.toLowerCase();
611	        for (Pet pet : getPetsInternal()) {
612	            if (!ignoreNew || !pet.isNew()) {
613	                String compName = pet.getName();
614	                compName = compName.toLowerCase();
615	                if (compName.equals(name)) {
616	                    return pet;
617	                }
618	            }
619	        }
620	        return null;
621	    }
622	
623	    public Pet getPet(Integer petId) {
624	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
625	    }
626	
627	    @Override
628	    public String toString() {
629	        return new ToStringCreator(this)
630	
631	            .append("id", this.getId())
632	            .append("new", this.isNew())
633	            .append("lastName", this.getLastName())
634	            .append("firstName", this.getFirstName())
635	            .append("address", this.address)
636	            .append("city", this.city)
637	            .append("telephone", this.telephone)
638	            .append("email", this.email)
639	            .toString();
640	    }
641	}
