3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * The single duplicate check on create, keyed on the household. A household is
11	 * {@code (lastName, postcode)} (see {@link Households}), so two owners that share a last
12	 * name and postcode are the same household and the second is rejected as a household
13	 * duplicate via {@link DuplicateHouseholdException} (409).
14	 *
15	 * <p>The {@code sharesHousehold} request flag bypasses this block entirely: a request that
16	 * opts in is a declared household member and is always created (it is also not flagged as a
17	 * possible duplicate — see {@link FlagPossibleDuplicate}). An owner with no postcode belongs
18	 * to no household and so can never collide here.
19	 *
20	 * <p>The household id is derived from the request's last name and postcode and compared
21	 * against the id each existing owner computes from its own last name and postcode, so the
22	 * check and {@link AssignHousehold}'s stamp cannot drift apart.
23	 */
24	public class EnsureUniqueHousehold {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateHouseholdException {
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return;
30	        }
31	        String householdId = Households.householdId(request.getLastName(), request.getPostcode());
32	        if (householdId == null) {
33	            return;
34	        }
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (existing.getId() == null) {
37	                continue;
38	            }
39	            if (householdId.equals(Households.householdId(existing.getLastName(), existing.getPostcode()))) {
40	                throw new DuplicateHouseholdException(householdId);
41	            }
42	        }
43	    }
